<?php
use App\Core\DB;use App\Core\Auth;use App\Core\Csrf;use App\Core\U;use App\Core\Audit;use App\Core\Secret;use App\Core\Site;use App\Services\ReservationService;use App\Services\GeminiService;use App\Services\UploadService;use App\Services\ICalService;use App\Controllers\WhatsappController;
if (!defined('SUITES_PAGE_ENTRY')) { http_response_code(404); exit; }

  Auth::requirePerm('guests.view');
  $edit=null;if(isset($_GET['id'])){$q=$pdo->prepare("SELECT * FROM guests WHERE id=?");$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}
  if($_SERVER['REQUEST_METHOD']==='POST'){
    Csrf::check();$id=(int)($_POST['id']??0);
    $vals=[trim($_POST['name']),trim($_POST['document']),$_POST['birth_date']?:null,trim($_POST['phone']),trim($_POST['whatsapp']),trim($_POST['email']),trim($_POST['address']),trim($_POST['city']),trim($_POST['state']),trim($_POST['country']),trim($_POST['nationality']),trim($_POST['language']),$_POST['notes'],$_POST['accessibility'],(int)$_POST['children'],isset($_POST['privacy_consent'])?1:0];
    if($id){$vals[]=$id;$pdo->prepare("UPDATE guests SET name=?,document=?,birth_date=?,phone=?,whatsapp=?,email=?,address=?,city=?,state=?,country=?,nationality=?,language=?,notes=?,accessibility=?,children=?,privacy_consent=?,updated_at=NOW() WHERE id=?")->execute($vals);}
    else{$pdo->prepare("INSERT INTO guests(name,document,birth_date,phone,whatsapp,email,address,city,state,country,nationality,language,notes,accessibility,children,privacy_consent,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())")->execute($vals);$id=(int)$pdo->lastInsertId();}
    Audit::log('guest.save','guest',$id);U::flash('ok','Hóspede salvo.');U::redirect('index.php?p=guests&id='.$id);
  }
  $gs=$pdo->query("SELECT * FROM guests ORDER BY id DESC LIMIT 500")->fetchAll();$x=$edit?:['id'=>'','name'=>'','document'=>'','birth_date'=>'','phone'=>'','whatsapp'=>'','email'=>'','address'=>'','city'=>'','state'=>'','country'=>'','nationality'=>'','language'=>'','notes'=>'','accessibility'=>'','children'=>0,'privacy_consent'=>0];
  $h=adminTitle('Hóspedes','Cadastro, dados de check-in e necessidades de acessibilidade.').'<div class=split><div class=card><h2>Hóspedes cadastrados</h2><table><tr><th>Nome</th><th>E-mail</th><th>WhatsApp</th><th></th></tr>';foreach($gs as $g)$h.='<tr><td>'.U::e($g['name']).'</td><td>'.U::e($g['email']).'</td><td>'.U::e($g['whatsapp']).'</td><td><a href="index.php?p=guests&id='.$g['id'].'">Editar</a></td></tr>';$h.='</table></div><form method=post class=card>'.Csrf::field().'<input type=hidden name=id value="'.U::e($x['id']).'"><h2>'.($edit?'Editar hóspede':'Novo hóspede').'</h2><div class=grid3>'.row('Nome completo','name',$x['name']).row('Documento','document',$x['document']).row('Nascimento','birth_date',$x['birth_date'],'date').row('Telefone','phone',$x['phone']).row('WhatsApp','whatsapp',$x['whatsapp']).row('E-mail','email',$x['email'],'email').row('Endereço','address',$x['address']).row('Cidade','city',$x['city']).row('Estado','state',$x['state']).row('País','country',$x['country']).row('Nacionalidade','nationality',$x['nationality']).row('Idioma','language',$x['language']).row('Crianças','children',$x['children'],'number').'</div>'.row('Observações','notes',$x['notes'],'textarea').row('Necessidades de acessibilidade','accessibility',$x['accessibility'],'textarea').row('Consentimento de privacidade registrado','privacy_consent',$x['privacy_consent'],'checkbox').'<button>Salvar hóspede</button></form></div>';render('Hóspedes',$h);exit;
